+    const root = repo();
+    commit(root, "loop-16-qa-report-4.md", "2026-09-29T12:00:00+00:00");
+    expect(describeLatestBrief(root)).toBeNull();
+  });
+
+  it("T210-2b: no docs/loops at all is also omitted", () => {
+    const root = mkdtempSync(join(tmpdir(), "latest-brief-"));
