+    expect(out).toMatch(/^Latest brief: not determined \(/);
+  });
+
+  it("T210-2c: no docs/loops directory is omitted even outside a git repository", () => {
+    const root = mkdtempSync(join(tmpdir(), "latest-brief-"));
+    made.push(root);
